import Foundation
import Network
import Security
import os.log

// MARK: - HTTPS / TLS Support
// Adds an optional TLS listener alongside the plain HTTP listener.
// The TLS identity is loaded from a PKCS12 file generated by the
// macOS host app's TLSCertificateManager.

public struct HTTPSConfig: Sendable {
    public let port: Int
    public let identityPath: String

    public init(port: Int, identityPath: String) {
        self.port = port
        self.identityPath = identityPath
    }
}

extension QuotaHTTPServer {

    func startHTTPSListener(config: HTTPSConfig, host: NWEndpoint.Host) async throws -> NWListener {
        final class ListenerStartState: @unchecked Sendable {
            private let lock = NSLock()
            private var hasResolved = false

            func resolve(
                continuation: CheckedContinuation<Void, Error>,
                result: Result<Void, Error>
            ) {
                lock.lock()
                defer { lock.unlock() }
                guard !hasResolved else { return }
                hasResolved = true
                continuation.resume(with: result)
            }
        }

        let (identity, chain) = try loadTLSIdentity(from: config.identityPath)

        let tlsOptions = NWProtocolTLS.Options()
        let secIdentity: sec_identity_t
        if !chain.isEmpty {
            guard let id = sec_identity_create_with_certificates(identity, chain as CFArray) else {
                throw TLSSetupError.identityCreationFailed
            }
            secIdentity = id
        } else {
            guard let id = sec_identity_create(identity) else {
                throw TLSSetupError.identityCreationFailed
            }
            secIdentity = id
        }
        sec_protocol_options_set_local_identity(
            tlsOptions.securityProtocolOptions,
            secIdentity
        )

        let params = NWParameters(tls: tlsOptions, tcp: .init())
        guard let httpsPort = NWEndpoint.Port(rawValue: UInt16(config.port)) else {
            throw QuotaHTTPServerError.invalidPort(config.port)
        }
        params.requiredLocalEndpoint = NWEndpoint.hostPort(host: host, port: httpsPort)

        let listener = try NWListener(using: params)
        listener.newConnectionHandler = { [weak self] connection in
            guard let self else { return }
            Task { await self.handleConnection(connection) }
        }

        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            let startState = ListenerStartState()
            listener.stateUpdateHandler = { state in
                switch state {
                case .ready:
                    startState.resolve(continuation: continuation, result: .success(()))
                case .failed(let error):
                    startState.resolve(continuation: continuation, result: .failure(error))
                case .cancelled:
                    startState.resolve(continuation: continuation, result: .failure(CancellationError()))
                default:
                    break
                }
            }
            listener.start(queue: .global())
        }

        httpLog.info("HTTPS listener ready on port \(config.port)")
        return listener
    }

    // MARK: - Identity Loading

    public static func supportsMemoryOnlyTLSIdentityImport(isMacOS15OrLater: Bool? = nil) -> Bool {
        if let isMacOS15OrLater { return isMacOS15OrLater }
        if #available(macOS 15.0, *) { return true }
        return false
    }

    func loadTLSIdentity(
        from path: String,
        requireMemoryOnlyImport: Bool = true,
        isMacOS15OrLater: Bool? = nil
    ) throws -> (SecIdentity, [SecCertificate]) {
        guard Self.supportsMemoryOnlyTLSIdentityImport(isMacOS15OrLater: isMacOS15OrLater) else {
            throw TLSSetupError.identityLoadFailed(errSecUnimplemented)
        }

        let identityURL = URL(fileURLWithPath: path).standardizedFileURL
        try validateOwnerOnlyFile(identityURL)
        let data = try Data(contentsOf: identityURL)

        let password: String
        if let envPassword = ProcessInfo.processInfo.environment["TLS_IDENTITY_PASSWORD"]?
            .trimmingCharacters(in: .whitespacesAndNewlines),
           !envPassword.isEmpty {
            password = envPassword
        } else {
            let passwordURL = identityURL.deletingLastPathComponent().appendingPathComponent(".identity-pass")
            try validateOwnerOnlyFile(passwordURL)
            guard let filePassword = String(data: try Data(contentsOf: passwordURL), encoding: .utf8)?
                .trimmingCharacters(in: .whitespacesAndNewlines),
                  !filePassword.isEmpty else {
                throw TLSSetupError.identityLoadFailed(errSecAuthFailed)
            }
            password = filePassword
        }

        var importItems: CFArray?
        var importParams: [String: Any] = [
            kSecImportExportPassphrase as String: password
        ]
        if #available(macOS 15.0, *) {
            importParams[kSecImportToMemoryOnly as String] = kCFBooleanTrue
        } else if requireMemoryOnlyImport {
            throw TLSSetupError.identityLoadFailed(errSecUnimplemented)
        }
        let status = SecPKCS12Import(data as CFData, importParams as CFDictionary, &importItems)

        guard status == errSecSuccess else {
            throw TLSSetupError.identityLoadFailed(status)
        }

        guard let array = importItems as? [[String: Any]],
              let first = array.first else {
            throw TLSSetupError.identityLoadFailed(errSecItemNotFound)
        }

        let chain = first[kSecImportItemCertChain as String] as? [SecCertificate] ?? []

        guard let identity = first[kSecImportItemIdentity as String] else {
            throw TLSSetupError.identityLoadFailed(errSecItemNotFound)
        }
        return (identity as! SecIdentity, chain) // swiftlint:disable:this force_cast
    }

    private func validateOwnerOnlyFile(_ url: URL) throws {
        var st = stat()
        guard lstat(url.path, &st) == 0,
              (st.st_mode & S_IFMT) == S_IFREG,
              (st.st_mode & 0o077) == 0 else {
            throw TLSSetupError.identityLoadFailed(errSecParam)
        }
    }
}

// MARK: - TLS Errors

enum TLSSetupError: LocalizedError {
    case identityLoadFailed(OSStatus)
    case identityCreationFailed

    var errorDescription: String? {
        switch self {
        case .identityLoadFailed(let status):
            return "Failed to load TLS identity (OSStatus: \(status))"
        case .identityCreationFailed:
            return "Failed to create sec_identity_t from SecIdentity"
        }
    }
}
